# Indonesian 14 and 16 share the same sentence; the drawing one says drawings.
FAQ_EDITS["faq_studio_14_a"][6] = ("Paket gratis membuat 2 gambar per hari, masing-masing setelah iklan singkat;", "Paket gratis membuat total 5 lukisan atau gambar per hari, masing-masing setelah iklan singkat dan dengan tanda Photo Plus;")

root = os.path.join(HERE, '../../../src/i18n/strings')
tables = {l: json.load(open(os.path.join(root, f'{l}.json'))) for l in LANGS}
for key, vals in S.items():
    assert len(vals) == len(LANGS), key
    for l, v in zip(LANGS, vals):
        tables[l][key] = v
for key, edits in FAQ_EDITS.items():
    assert len(edits) == len(LANGS), key
    for l, (old, new) in zip(LANGS, edits):
        v = tables[l][key]
        if new in v: continue  # already done
        assert v.count(old) == 1, (l, key, old)
        tables[l][key] = v.replace(old, new)
for l in LANGS:
    p = os.path.join(root, f'{l}.json')
    json.dump(tables[l], open(p, 'w'), ensure_ascii=False, indent=2)
    open(p, 'a').write('\n')

# The earlier content scripts hold these sentences too: keep them in step (so they can be run again).
for script in ['faq_en.py', 'masters.py', 'pencil.py', 'toon.py']:
    p = os.path.join(HERE, script)
    s = open(p).read()
    for edits in FAQ_EDITS.values():
        for old, new in edits:
            s = s.replace(old, new)
    open(p, 'w').write(s)
print(len(S), 'strings and', sum(len(e) for e in FAQ_EDITS.values()), 'FAQ sentences in', len(LANGS), 'languages')
